inline std::string studio_html(const std::string& engine,bool login_required){
  std::string s=R"WEB(<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Neo Studio · Inferencia</title><style>
:root{font-family:Inter,system-ui,-apple-system,Segoe UI,sans-serif;color-scheme:dark;--bg:#0c1018;--panel:#151c29;--line:#2c3951;--text:#eaf0ff;--muted:#9cabbe;--brand:#96b9ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse 80% 35% at 65% -10%,#253858,transparent),var(--bg);color:var(--text)}.layout{min-height:100vh;display:grid;grid-template-columns:224px minmax(0,1fr)}aside{border-right:1px solid var(--line);padding:30px 20px;background:#101622}.brand{display:flex;gap:12px;align-items:center;font-weight:800;font-size:19px}.mark{display:grid;place-items:center;background:var(--brand);color:#101b31;width:37px;height:37px;border-radius:10px;font-size:22px}.brand small{display:block;font-size:9px;letter-spacing:1.3px;color:var(--muted)}.nav{margin-top:40px;padding:13px;border-radius:9px;border:1px solid #405377;background:#243550;color:#dbe9ff;font-size:13px}.aside-bottom{margin-top:35px;font-size:12px;color:var(--muted)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#4edaa0;margin-right:8px}main{max-width:1190px;width:100%;padding:55px 40px;margin:0 auto}.eyebrow{font-size:11px;letter-spacing:2px;font-weight:700;color:var(--brand)}h1{font-size:clamp(31px,4.5vw,53px);letter-spacing:-1.8px;margin:10px 0}p{color:var(--muted);line-height:1.65}.grid{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:38px}.card{border:1px solid var(--line);background:linear-gradient(130deg,#182132,var(--panel));border-radius:17px;padding:28px;min-width:0;box-shadow:0 16px 48px #0002}.card h2{font-size:17px;margin:0 0 22px}.idx{color:var(--brand);border:1px solid #405474;padding:6px 8px;border-radius:7px;font-size:12px;margin-right:10px}label{display:block;font-weight:600;font-size:13px;color:#d1ddef;margin-bottom:10px}textarea,input{width:100%;border:1px solid #394b66;border-radius:9px;background:#0c1422;padding:15px;color:var(--text);outline:0;font:inherit}textarea{min-height:250px;resize:vertical;line-height:1.65}textarea:focus,input:focus{border-color:var(--brand)}.meta{display:flex;justify-content:space-between;gap:8px;color:var(--muted);font-size:12px;margin-top:10px}.btn{font:700 14px inherit;border-radius:9px;padding:13px 17px;cursor:pointer;border:1px solid #455a7c;background:#233247;color:#eaf0ff}.btn.primary{background:var(--brand);border-color:var(--brand);color:#0f1c31}.btn:disabled{opacity:.55;cursor:wait}.actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:20px}#status{font-size:12px;color:#bbcae2;margin-top:17px;min-height:20px}.empty{color:var(--muted);padding:45px 18px;border:1px dashed #3a4b67;border-radius:10px;text-align:center;line-height:1.7}.hidden{display:none!important}.visual{background:#090f1b;border:1px solid #34435c;padding:14px;border-radius:10px}canvas{display:block;width:100%;height:145px}.switch{display:flex;gap:8px;margin-bottom:12px}.switch button{padding:7px 12px;border-radius:7px;background:#182337;color:#a2b6d2;border:1px solid var(--line);cursor:pointer}.switch button.active{background:#294366;color:#fff}audio{width:100%;margin-top:20px}.download{display:inline-block;text-decoration:none;border-radius:9px;background:#97baff;color:#0c182e;font-weight:800;padding:12px 16px;font-size:13px}.result-meta{font-size:12px;color:var(--muted);margin:12px 0}.login{position:fixed;inset:0;z-index:10;display:grid;place-items:center;background:#080c15ef;padding:20px}.login .card{width:min(400px,100%)}.login input{margin-bottom:17px}.hint{font-size:12px;color:var(--muted)}@media(max-width:950px){.grid{grid-template-columns:1fr}main{padding:35px 20px}}@media(max-width:600px){.layout{grid-template-columns:1fr}aside{padding:14px;border-right:0;border-bottom:1px solid var(--line)}.nav,.aside-bottom{display:none}.grid{margin-top:25px}.card{padding:19px}}
</style></head><body><div class="layout"><aside><div class="brand"><span class="mark">◈</span><span>NEO Studio<small>VOICE INFERENCE</small></span></div><div class="nav">◉ &nbsp; Inferencia de voz</div><div class="aside-bottom"><span class="dot"></span> Motor nativo activo</div></aside><main><div class="eyebrow">NEURAL VOICE · C++/ONNX RUNTIME</div><h1>Inferencia de voz</h1><p>Escribe tu texto, genera audio y analiza la forma de onda. La exportación y Hugging Face se gestionan desde el CLI.</p><div class="grid"><section class="card"><h2><span class="idx">01</span>Entradas</h2><label for="text">Texto de síntesis</label><textarea id="text" maxlength="4000" placeholder="Escribe tu texto...">Hello, this is Neo Studio speaking with a natural neural voice.</textarea><div class="meta"><span id="engine"></span><span id="count">0 / 4096 bytes</span></div><div class="actions"><button class="btn primary" id="go">✦ Generar audio</button></div><div id="status" role="status" aria-live="polite">Motor listo.</div></section><section class="card"><h2><span class="idx">02</span>Resultado</h2><div id="empty" class="empty">Tu audio aparecerá aquí, con su reproductor, forma de onda, espectro y descarga WAV.</div><div id="result" class="hidden"><div class="switch"><button data-view="wave" class="active">Forma de onda</button><button data-view="spectrum">Espectro</button></div><div class="visual"><canvas id="wave" width="620" height="145" aria-label="Forma de onda"></canvas><canvas id="spectrum" class="hidden" width="620" height="145" aria-label="Espectro de frecuencias"></canvas></div><div class="result-meta" id="audioMeta"></div><audio id="audio" controls></audio><div class="actions"><a class="download" id="save" download="neo-voz.wav">↓ Descargar WAV</a><button class="btn" id="play">↻ Reproducir</button></div></div></section></div></main></div><div id="login" class="login hidden"><form id="loginForm" class="card"><h2>Acceso privado</h2><p>Introduce las credenciales del servidor de inferencia.</p><label for="username">Usuario</label><input id="username" autocomplete="username" required><label for="password">Contraseña</label><input id="password" type="password" autocomplete="current-password" required><button class="btn primary" type="submit">Acceder</button><p id="loginStatus" class="hint"></p></form></div><script>
const $=id=>document.getElementById(id),ENGINE=__ENGINE_JSON__,LOGIN=__LOGIN_REQUIRED__;let auth='',url='';$('engine').textContent=ENGINE;if(LOGIN)$('login').classList.remove('hidden');
const size=text=>new TextEncoder().encode(text).length;$('text').oninput=()=>$('count').textContent=size($('text').value)+' / 4096 bytes';$('text').oninput();
async function request(path,opts={}){const headers={...(opts.headers||{})};if(auth)headers.Authorization=auth;const r=await fetch(path,{...opts,headers});if(r.status===401){$('login').classList.remove('hidden');throw Error('Sesión caducada o credenciales incorrectas')}if(!r.ok)throw Error('HTTP '+r.status);return r}
$('loginForm').onsubmit=async e=>{e.preventDefault();auth='Basic '+btoa(unescape(encodeURIComponent($('username').value+':'+$('password').value)));try{await request('/api/health');$('login').classList.add('hidden');$('password').value='';$('loginStatus').textContent=''}catch(err){auth='';$('loginStatus').textContent=err.message}};
async function analyze(blob){try{const raw=await blob.arrayBuffer(),audio=await new (window.AudioContext||window.webkitAudioContext)().decodeAudioData(raw.slice(0));const s=audio.getChannelData(0),sr=audio.sampleRate;const canvas=$('wave'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#95baff';ctx.lineWidth=1.6;ctx.beginPath();for(let x=0;x<w;++x){const a=Math.floor(x*s.length/w),b=Math.min(s.length,Math.floor((x+1)*s.length/w));let m=0;for(let i=a;i<b;++i)m=Math.max(m,Math.abs(s[i]));ctx.moveTo(x,h/2-m*h*.45);ctx.lineTo(x,h/2+m*h*.45)}ctx.stroke();const c=$('spectrum'),g=c.getContext('2d'),N=512,hop=Math.max(128,Math.floor(s.length/c.width)),bins=56,db=[];for(let x=0;x<c.width;++x){const start=Math.min(Math.max(0,s.length-N),Math.floor(x*hop));for(let k=0;k<bins;++k){let re=0,im=0;const freq=k+1;for(let t=0;t<N;t+=4){const y=s[start+t]||0,a=2*Math.PI*freq*t/N;re+=y*Math.cos(a);im-=y*Math.sin(a)}const level=Math.log1p(Math.hypot(re,im))/4;g.fillStyle='hsl('+(210+level*65)+',75%,'+(8+Math.min(65,level*70))+'%)';g.fillRect(x,c.height-(k+1)*c.height/bins,1,c.height/bins+1)}}$('audioMeta').textContent=audio.duration.toFixed(2)+' s · '+sr+' Hz · '+(blob.size/1048576).toFixed(2)+' MiB'}catch(e){$('audioMeta').textContent='WAV · '+(blob.size/1048576).toFixed(2)+' MiB'}}
for(const b of document.querySelectorAll('.switch button'))b.onclick=()=>{const view=b.dataset.view;for(const x of document.querySelectorAll('.switch button'))x.classList.toggle('active',x===b);$('wave').classList.toggle('hidden',view!=='wave');$('spectrum').classList.toggle('hidden',view!=='spectrum')};
$('play').onclick=()=>$('audio').play();$('go').onclick=async()=>{const text=$('text').value;if(!text.trim()||size(text)>4096){$('status').textContent='Texto vacío o demasiado largo';return}const btn=$('go');btn.disabled=true;$('status').textContent='Generando audio...';try{const r=await request('/api/synthesize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})});const wav=await r.blob();if(url)URL.revokeObjectURL(url);url=URL.createObjectURL(wav);$('audio').src=url;$('save').href=url;$('empty').classList.add('hidden');$('result').classList.remove('hidden');$('status').textContent='Audio generado correctamente';await analyze(wav)}catch(e){$('status').textContent=e.message}finally{btn.disabled=false}};
</script></body></html>)WEB";
  const auto quote=[](const std::string& input){std::string out="\"";for(unsigned char c:input){if(c=='"'||c=='\\'){out+='\\';out+=c;}else if(c<32)out+=' ';else out+=c;}return out+'"';};
  const auto replace=[&](const std::string& key,const std::string& value){auto pos=s.find(key);if(pos!=std::string::npos)s.replace(pos,key.size(),value);};
  replace("__ENGINE_JSON__",quote(engine));replace("__LOGIN_REQUIRED__",login_required?"true":"false");return s;
}
